const bySlug = {};
for (const p of items) {
  const b = (p.json && p.json.body) || {};
  for (const k of (b.keys || [])) {
    for (const t of (k.tags || [])) {
      const s = String(t);
      if (s.indexOf('page::') !== 0) continue;
      const slug = s.slice(6);
      if (!bySlug[slug]) bySlug[slug] = [];
      bySlug[slug].push(k.key_id);
    }
  }
}
const out = [];
const skipped = [];
for (const slug in bySlug) {
  const meta = SCREENS[slug];
  if (!meta) { skipped.push({ slug: slug, keys: bySlug[slug].length }); continue; }
  out.push({ json: {
    slug: slug,
    title: meta[1],
    description: 'Figma: All Mockups - NEW [copy changes] > ' + meta[2] + '. Desktop and mobile shown side by side.',
    image_url: BASE + meta[0] + '.png',
    key_ids: bySlug[slug],
    key_count: bySlug[slug].length,
    skipped_slugs: skipped
  }});
}
return out;

const res = $input.all();
let ok = 0;
const uploaded = [];
const errors = [];
for (const r of res) {
  const j = r.json || {};
  const b = j.body || {};
  if (j.statusCode === 200 && b.screenshots && b.screenshots.length) {
    ok++;
    for (const s of b.screenshots) {
      uploaded.push({ screenshot_id: s.screenshot_id, title: s.title, keys: (s.key_ids || []).length });
    }
  } else {
    errors.push({ statusCode: j.statusCode, err: JSON.stringify(b).slice(0, 300) });
  }
}
return [{ json: { screens: res.length, ok: ok, uploaded: uploaded, errors: errors } }];

const job = $('Loop Screens').first().json;
let b64 = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  b64 = buf.toString('base64');
} catch (e) {
  const it = $input.first();
  const bin = (it.binary && it.binary.data) ? it.binary.data : null;
  b64 = (bin && bin.data && bin.data !== 'filesystem-v2') ? bin.data : '';
}
if (!b64 || b64.length < 1000) {
  return [{ json: { slug: job.slug, error: 'no image bytes (' + b64.length + ')', skip: true, url: 'https://api.lokalise.com/api2/projects/185916266aa3d6649ca6f7.57851232/screenshots', body: { screenshots: [] } } }];
}
const payload = {
  data: 'data:image/png;base64,' + b64,
  title: job.title,
  description: job.description,
  ocr: false,
  key_ids: job.key_ids
};
return [{ json: {
  slug: job.slug,
  key_count: job.key_count,
  b64_len: b64.length,
  skip: false,
  url: 'https://api.lokalise.com/api2/projects/185916266aa3d6649ca6f7.57851232/screenshots',
  body: { screenshots: [payload] }
} }];
